var jshover=function(){var b=document.getElementById("horizontal-multilevel-menu");if(!b){return}var a=b.getElementsByTagName("li");for(var c=0;c<a.length;c++){a[c].onmouseover=function(){this.className+=" jshover"};a[c].onmouseout=function(){this.className=this.className.replace(new RegExp(" jshover\\b"),"")}}};if(window.attachEvent){window.attachEvent("onload",jshover)};